
/*
  # Create system user and seed predefined templates/macros

  ## Overview
  1. Creates a system user in auth.users for system-level templates and macros
  2. Seeds 20 predefined radiology report templates across all modalities
  3. Seeds 10 system-level macros for common findings
  4. Adds RLS policies for all authenticated users to read system resources

  ## Templates (20)
  CT: Chest Normal, Lung Cancer, PE, Abdomen Normal, Kidney Stone, Head Normal, Stroke
  MRI: Brain Normal, MS
  X-Ray: Chest Normal, Pneumonia, Rib Fracture
  Ultrasound: Abdomen Normal, Kidney Stone, Gallstones, Pelvis Normal, Thyroid Normal, Obstetric 1st Tri
  PET-CT: Oncology Staging
  Mammography: Normal

  ## Macros (10)
  US: /us-normal-abd, /us-normal-kidney, /us-gallstones, /us-kidney-stone, /us-normal-thyroid, /us-normal-pelvis
  CT: /ct-normal-chest, /ct-normal-abd, /ct-normal-brain
  MRI: /mri-normal-brain
*/

-- Create system user in auth.users
INSERT INTO auth.users (
  id, instance_id, aud, role, email, encrypted_password, email_confirmed_at,
  created_at, updated_at, confirmation_token, email_change, recovery_token
) VALUES (
  '00000000-0000-0000-0000-000000000000',
  '00000000-0000-0000-0000-000000000000',
  'authenticated',
  'authenticated',
  'system@radai.internal',
  extensions.crypt(
  'system-placeholder-not-for-login',
  extensions.gen_salt('bf')
),
  now(),
  now(),
  now(),
  '',
  '',
  ''
) ON CONFLICT (id) DO NOTHING;

-- Create system profile
INSERT INTO profiles (id, name, role, specialty) VALUES
  ('00000000-0000-0000-0000-000000000000', 'System', 'system', 'general')
ON CONFLICT (id) DO NOTHING;

-- RLS policies for system resources
CREATE POLICY "Authenticated users can read system templates"
  ON templates FOR SELECT
  TO authenticated
  USING (user_id = '00000000-0000-0000-0000-000000000000');

CREATE POLICY "Authenticated users can read system macros"
  ON macros FOR SELECT
  TO authenticated
  USING (user_id = '00000000-0000-0000-0000-000000000000');

-- ============ TEMPLATES ============

INSERT INTO templates (user_id, name, description, scan_type, structure, conditions, is_default, usage_count) VALUES
('00000000-0000-0000-0000-000000000000', 'CT Chest - Normal', 'Standard normal CT chest report format', 'CT Chest',
'[{"id":"s1","label":"Technique","placeholder":"Helical CT of the chest was performed with intravenous contrast...","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Reason for examination...","required":true,"type":"text"},{"id":"s3","label":"Findings","placeholder":"The lungs are clear bilaterally without focal consolidation, pleural effusion, or pneumothorax...","required":true,"type":"text"},{"id":"s4","label":"Impression","placeholder":"1. No acute cardiopulmonary abnormality.","required":true,"type":"text"}]'::jsonb, '[]'::jsonb, true, 0),

('00000000-0000-0000-0000-000000000000', 'CT Chest - Pulmonary Nodule / Lung Cancer', 'Comprehensive format for pulmonary nodule or lung cancer with measurement and staging', 'CT Chest',
'[{"id":"s1","label":"Technique","placeholder":"Helical CT of the chest was performed with intravenous contrast...","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Known or suspected pulmonary nodule...","required":true,"type":"text"},{"id":"s3","label":"Nodule Characteristics","placeholder":"Location, size, morphology, attenuation, margins...","required":true,"type":"text"},{"id":"s4","label":"Findings - Lungs","placeholder":"Description of pulmonary parenchyma including nodule details...","required":true,"type":"text"},{"id":"s5","label":"Findings - Mediastinum","placeholder":"Mediastinal and hilar lymph nodes...","required":true,"type":"text"},{"id":"s6","label":"Findings - Other","placeholder":"Pleura, pericardium, chest wall, upper abdomen...","required":false,"type":"text"},{"id":"s7","label":"Staging (if malignancy)","placeholder":"T: , N: , M: , Stage:","required":false,"type":"text"},{"id":"s8","label":"Impression","placeholder":"1. Pulmonary nodule... 2. Recommendations...","required":true,"type":"text"}]'::jsonb,
'[{"id":"c1","trigger_keyword":"lung nodule","add_section":"Nodule Characteristics","section_content":"A pulmonary nodule is identified. Size, location, morphology, and attenuation characteristics are described below. Lung-RADS classification recommended."},{"id":"c2","trigger_keyword":"lung cancer","add_section":"Staging (if malignancy)","section_content":"TNM staging assessment based on current imaging findings. Primary tumor: [T]. Regional lymph nodes: [N]. Distant metastasis: [M]."},{"id":"c3","trigger_keyword":"metastasis","add_section":"Staging (if malignancy)","section_content":"Evidence of metastatic disease. Sites involved: [specify]."}]'::jsonb, false, 0),

('00000000-0000-0000-0000-000000000000', 'CT Chest - Pulmonary Embolism', 'Format for CT pulmonary angiography with PE reporting', 'CT Chest',
'[{"id":"s1","label":"Technique","placeholder":"CT pulmonary angiography was performed following intravenous administration of contrast...","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Suspected pulmonary embolism...","required":true,"type":"text"},{"id":"s3","label":"Pulmonary Arteries","placeholder":"Description of filling defects, location, and extent...","required":true,"type":"text"},{"id":"s4","label":"Findings - Cardiac","placeholder":"Right ventricular size, interventricular septum, RV/LV ratio...","required":true,"type":"text"},{"id":"s5","label":"Findings - Lungs","placeholder":"Parenchymal abnormalities, infarction, effusions...","required":false,"type":"text"},{"id":"s6","label":"Impression","placeholder":"1. Acute pulmonary embolism...","required":true,"type":"text"}]'::jsonb,
'[{"id":"c1","trigger_keyword":"pulmonary embolism","add_section":"Pulmonary Arteries","section_content":"Filling defect(s) identified in the pulmonary arterial system. Location and extent to be specified."},{"id":"c2","trigger_keyword":"right heart strain","add_section":"Findings - Cardiac","section_content":"Signs of right heart strain: RV/LV ratio >1.0, interventricular septum bowing, reflux of contrast into IVC/hepatic veins."}]'::jsonb, false, 0),

('00000000-0000-0000-0000-000000000000', 'CT Abdomen/Pelvis - Normal', 'Standard normal CT abdomen and pelvis report', 'CT Abdomen/Pelvis',
'[{"id":"s1","label":"Technique","placeholder":"Helical CT of the abdomen and pelvis was performed with intravenous and oral contrast...","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Reason for examination...","required":true,"type":"text"},{"id":"s3","label":"Findings - Liver","placeholder":"The liver is normal in size and attenuation without focal lesion...","required":true,"type":"text"},{"id":"s4","label":"Findings - Biliary","placeholder":"The gallbladder is normal. No biliary dilatation...","required":true,"type":"text"},{"id":"s5","label":"Findings - Pancreas","placeholder":"The pancreas is normal without focal lesion or ductal dilatation...","required":true,"type":"text"},{"id":"s6","label":"Findings - Spleen","placeholder":"The spleen is normal in size...","required":true,"type":"text"},{"id":"s7","label":"Findings - Kidneys","placeholder":"The kidneys enhance symmetrically without focal lesion or hydronephrosis...","required":true,"type":"text"},{"id":"s8","label":"Findings - Bowel","placeholder":"The bowel is normal in caliber and enhancement...","required":false,"type":"text"},{"id":"s9","label":"Findings - Other","placeholder":"No free fluid, lymphadenopathy, or osseous abnormality...","required":false,"type":"text"},{"id":"s10","label":"Impression","placeholder":"1. No acute abdominal or pelvic abnormality.","required":true,"type":"text"}]'::jsonb, '[]'::jsonb, true, 0),

('00000000-0000-0000-0000-000000000000', 'CT Abdomen/Pelvis - Kidney Stone', 'Format for renal calculus reporting with measurements and hydronephrosis', 'CT Abdomen/Pelvis',
'[{"id":"s1","label":"Technique","placeholder":"Non-contrast CT of the abdomen and pelvis (stone protocol)...","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Flank pain, suspected nephrolithiasis...","required":true,"type":"text"},{"id":"s3","label":"Findings - Kidneys","placeholder":"Right kidney: [stone size, location, hydronephrosis]. Left kidney: [stone size, location, hydronephrosis]...","required":true,"type":"text"},{"id":"s4","label":"Findings - Ureters","placeholder":"Ureteral calculi, location and size...","required":true,"type":"text"},{"id":"s5","label":"Findings - Bladder","placeholder":"Bladder status...","required":false,"type":"text"},{"id":"s6","label":"Findings - Other","placeholder":"Other abdominal findings...","required":false,"type":"text"},{"id":"s7","label":"Impression","placeholder":"1. Calculus identified... Size, location, hydronephrosis status...","required":true,"type":"text"}]'::jsonb,
'[{"id":"c1","trigger_keyword":"kidney stone","add_section":"Findings - Kidneys","section_content":"Renal calculus identified. Size: [X] mm. Location: [right/left kidney, specific location]. Associated hydronephrosis: [present/absent]."},{"id":"c2","trigger_keyword":"hydronephrosis","add_section":"Findings - Ureters","section_content":"Hydronephrosis noted. Assess for level of obstruction - ureteral calculus vs. extrinsic compression."}]'::jsonb, false, 0),

('00000000-0000-0000-0000-000000000000', 'CT Head - Normal', 'Standard normal non-contrast CT head report', 'CT Head',
'[{"id":"s1","label":"Technique","placeholder":"Non-contrast CT of the head was performed...","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Reason for examination...","required":true,"type":"text"},{"id":"s3","label":"Findings","placeholder":"No intracranial hemorrhage, mass effect, or midline shift. The gray-white matter differentiation is preserved. The ventricles and sulci are normal in size and configuration. No acute territorial infarction. The basal cisterns are patent. The calvarium and skull base are intact.","required":true,"type":"text"},{"id":"s4","label":"Impression","placeholder":"1. No acute intracranial abnormality.","required":true,"type":"text"}]'::jsonb, '[]'::jsonb, true, 0),

('00000000-0000-0000-0000-000000000000', 'CT Head - Acute Stroke', 'Format for acute stroke CT head with ASPECTS scoring', 'CT Head',
'[{"id":"s1","label":"Technique","placeholder":"Non-contrast CT of the head. CTA head/neck if applicable...","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Acute neurological deficit, suspected stroke...","required":true,"type":"text"},{"id":"s3","label":"Findings - Parenchyma","placeholder":"ASPECTS score, early ischemic changes, hemorrhage assessment...","required":true,"type":"text"},{"id":"s4","label":"Findings - Vessels","placeholder":"CTA findings if performed...","required":false,"type":"text"},{"id":"s5","label":"Findings - Other","placeholder":"Ventricles, cisterns, calvarium...","required":false,"type":"text"},{"id":"s6","label":"Impression","placeholder":"1. Findings consistent with acute stroke... ASPECTS: X/10...","required":true,"type":"text"}]'::jsonb,
'[{"id":"c1","trigger_keyword":"stroke","add_section":"Findings - Parenchyma","section_content":"Assess for early ischemic changes. ASPECTS scoring: [score]/10. Territory involved: [MCA/ACA/PCA]."},{"id":"c2","trigger_keyword":"hemorrhage","add_section":"Findings - Parenchyma","section_content":"Intracranial hemorrhage identified. Type: [intraparenchymal/subarachnoid/subdural/epidural]. Location: [specify]. Volume estimate: [X] mL."}]'::jsonb, false, 0),

('00000000-0000-0000-0000-000000000000', 'MRI Brain - Normal', 'Standard normal MRI brain report', 'MRI Brain',
'[{"id":"s1","label":"Technique","placeholder":"MRI of the brain including T1, T2, FLAIR, and DWI sequences with and without gadolinium...","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Reason for examination...","required":true,"type":"text"},{"id":"s3","label":"Findings","placeholder":"No abnormal signal intensity on any sequence. No evidence of acute infarction on DWI. No enhancing lesion. The ventricles are normal. No mass effect or midline shift. The major intracranial flow voids are preserved. The paranasal sinuses and mastoid air cells are clear.","required":true,"type":"text"},{"id":"s4","label":"Impression","placeholder":"1. No acute intracranial abnormality. 2. Normal MRI of the brain.","required":true,"type":"text"}]'::jsonb, '[]'::jsonb, true, 0),

('00000000-0000-0000-0000-000000000000', 'MRI Brain - Multiple Sclerosis', 'Format for MS/demyelination MRI brain reporting', 'MRI Brain',
'[{"id":"s1","label":"Technique","placeholder":"MRI of the brain with and without gadolinium including T1, T2, FLAIR, DWI...","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Known or suspected demyelinating disease...","required":true,"type":"text"},{"id":"s3","label":"Findings - White Matter","placeholder":"Periventricular, juxtacortical, infratentorial, spinal cord lesions...","required":true,"type":"text"},{"id":"s4","label":"Findings - Enhancement","placeholder":"Enhancing vs non-enhancing lesions...","required":true,"type":"text"},{"id":"s5","label":"Findings - Other","placeholder":"Brain volume, ventricles, sinuses...","required":false,"type":"text"},{"id":"s6","label":"Impression","placeholder":"1. White matter lesions consistent with demyelinating disease... 2. Comparison with prior: [stable/new/enlarged]","required":true,"type":"text"}]'::jsonb, '[]'::jsonb, false, 0),

('00000000-0000-0000-0000-000000000000', 'X-Ray Chest - Normal', 'Standard normal chest X-ray report', 'X-Ray Chest',
'[{"id":"s1","label":"Technique","placeholder":"PA and lateral views of the chest...","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Reason for examination...","required":true,"type":"text"},{"id":"s3","label":"Findings","placeholder":"The lungs are clear bilaterally without focal consolidation, pleural effusion, or pneumothorax. The cardiac silhouette is within normal limits. The mediastinal contour is unremarkable. The osseous structures are intact.","required":true,"type":"text"},{"id":"s4","label":"Impression","placeholder":"1. No acute cardiopulmonary abnormality.","required":true,"type":"text"}]'::jsonb, '[]'::jsonb, true, 0),

('00000000-0000-0000-0000-000000000000', 'X-Ray Chest - Pneumonia', 'Format for pneumonia chest X-ray reporting', 'X-Ray Chest',
