('00000000-0000-0000-0000-000000000000', 'Ultrasound Abdomen - Normal', 'Standard normal abdominal ultrasound report', 'Ultrasound Abdomen',
'[{"id":"s1","label":"Technique","placeholder":"Ultrasound of the abdomen was performed with the patient in supine position...","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Reason for examination...","required":true,"type":"text"},{"id":"s3","label":"Findings - Liver","placeholder":"The liver is normal in size and echotexture without focal lesion. No intrahepatic biliary dilatation. Portal vein is patent with hepatopetal flow.","required":true,"type":"text"},{"id":"s4","label":"Findings - Gallbladder","placeholder":"The gallbladder is normal in size, wall thickness, and echotexture. No gallstones, sludge, or pericholecystic fluid.","required":true,"type":"text"},{"id":"s5","label":"Findings - Pancreas","placeholder":"The pancreas is normal in echotexture without focal lesion or ductal dilatation.","required":true,"type":"text"},{"id":"s6","label":"Findings - Spleen","placeholder":"The spleen is normal in size measuring [X] cm. No focal lesion.","required":true,"type":"text"},{"id":"s7","label":"Findings - Kidneys","placeholder":"Right kidney measures [X] cm, left kidney measures [X] cm. Both kidneys show normal cortical thickness and echogenicity. No hydronephrosis, calculus, or mass.","required":true,"type":"text"},{"id":"s8","label":"Findings - Aorta","placeholder":"The abdominal aorta is normal in caliber measuring [X] cm.","required":false,"type":"text"},{"id":"s9","label":"Impression","placeholder":"1. Normal abdominal ultrasound. 2. No evidence of solid organ abnormality, biliary pathology, or hydronephrosis.","required":true,"type":"text"}]'::jsonb, '[]'::jsonb, true, 0),

('00000000-0000-0000-0000-000000000000', 'Ultrasound Abdomen - Kidney Stone', 'Format for renal calculus ultrasound reporting', 'Ultrasound Abdomen',
'[{"id":"s1","label":"Technique","placeholder":"Ultrasound of the abdomen with focus on the urinary tract...","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Flank pain, hematuria, suspected nephrolithiasis...","required":true,"type":"text"},{"id":"s3","label":"Findings - Right Kidney","placeholder":"Right kidney: size, cortical thickness, echogenicity, calculus (size, location), hydronephrosis...","required":true,"type":"text"},{"id":"s4","label":"Findings - Left Kidney","placeholder":"Left kidney: size, cortical thickness, echogenicity, calculus (size, location), hydronephrosis...","required":true,"type":"text"},{"id":"s5","label":"Findings - Bladder","placeholder":"Urinary bladder: wall thickness, capacity, calculi, debris...","required":true,"type":"text"},{"id":"s6","label":"Findings - Other","placeholder":"Liver, gallbladder, pancreas, spleen...","required":false,"type":"text"},{"id":"s7","label":"Impression","placeholder":"1. [Right/Left/Bilateral] renal calculus measuring [X] mm. 2. [Hydronephrosis present/absent]. 3. Recommendations...","required":true,"type":"text"}]'::jsonb,
'[{"id":"c1","trigger_keyword":"kidney stone","add_section":"Findings - Right Kidney","section_content":"Renal calculus identified. Size: [X] mm. Location: [upper/mid/lower pole]. Echogenic focus with posterior acoustic shadowing. Associated hydronephrosis: [present/absent, grade]."},{"id":"c2","trigger_keyword":"hydronephrosis","add_section":"Findings - Right Kidney","section_content":"Hydronephrosis identified. Grade: [mild/moderate/severe]. Assess for level of obstruction."}]'::jsonb, false, 0),

('00000000-0000-0000-0000-000000000000', 'Ultrasound Abdomen - Gallstones / Cholecystitis', 'Format for gallbladder pathology ultrasound reporting', 'Ultrasound Abdomen',
'[{"id":"s1","label":"Technique","placeholder":"Ultrasound of the abdomen with focus on the gallbladder and biliary tree...","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Right upper quadrant pain, suspected cholecystitis...","required":true,"type":"text"},{"id":"s3","label":"Findings - Gallbladder","placeholder":"Gallbladder size, wall thickness, stones, sludge, Murphy sign, pericholecystic fluid...","required":true,"type":"text"},{"id":"s4","label":"Findings - Biliary Tree","placeholder":"Common bile duct diameter, intrahepatic ducts...","required":true,"type":"text"},{"id":"s5","label":"Findings - Other","placeholder":"Liver, pancreas, spleen, kidneys...","required":false,"type":"text"},{"id":"s6","label":"Impression","placeholder":"1. Cholelithiasis / Cholecystitis... 2. Biliary dilatation if present...","required":true,"type":"text"}]'::jsonb,
'[{"id":"c1","trigger_keyword":"cholecystitis","add_section":"Findings - Gallbladder","section_content":"Findings concerning for cholecystitis: gallbladder wall thickening >3mm, pericholecystic fluid, positive sonographic Murphy sign, gallstones."}]'::jsonb, false, 0),

('00000000-0000-0000-0000-000000000000', 'Ultrasound Pelvis - Normal (Female)', 'Standard normal female pelvic ultrasound report', 'Ultrasound Pelvis',
'[{"id":"s1","label":"Technique","placeholder":"Transabdominal and transvaginal ultrasound of the pelvis was performed...","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Reason for examination...","required":true,"type":"text"},{"id":"s3","label":"Findings - Uterus","placeholder":"The uterus is normal in size and echotexture. Endometrial thickness: [X] mm. No focal myometrial lesion.","required":true,"type":"text"},{"id":"s4","label":"Findings - Ovaries","placeholder":"Right ovary: [size, follicles]. Left ovary: [size, follicles]. No adnexal mass.","required":true,"type":"text"},{"id":"s5","label":"Findings - Cul-de-sac","placeholder":"No free fluid in the cul-de-sac.","required":false,"type":"text"},{"id":"s6","label":"Impression","placeholder":"1. Normal pelvic ultrasound. 2. No adnexal mass or free fluid.","required":true,"type":"text"}]'::jsonb, '[]'::jsonb, true, 0),

('00000000-0000-0000-0000-000000000000', 'Ultrasound Thyroid - Normal', 'Standard normal thyroid ultrasound report', 'Ultrasound Thyroid',
'[{"id":"s1","label":"Technique","placeholder":"Ultrasound of the thyroid gland was performed...","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Reason for examination...","required":true,"type":"text"},{"id":"s3","label":"Findings - Thyroid","placeholder":"The thyroid gland is normal in size and echotexture. Right lobe: [X] x [X] x [X] cm. Left lobe: [X] x [X] x [X] cm. Isthmus: [X] mm. No focal nodule or cyst.","required":true,"type":"text"},{"id":"s4","label":"Findings - Adjacent","placeholder":"No significant cervical lymphadenopathy.","required":false,"type":"text"},{"id":"s5","label":"Impression","placeholder":"1. Normal thyroid ultrasound. 2. No thyroid nodule or abnormality.","required":true,"type":"text"}]'::jsonb, '[]'::jsonb, true, 0),

('00000000-0000-0000-0000-000000000000', 'Ultrasound Obstetric - First Trimester', 'First trimester obstetric ultrasound report format', 'Ultrasound Obstetric',
'[{"id":"s1","label":"Technique","placeholder":"Transabdominal (and transvaginal if applicable) ultrasound...","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Dating, viability, bleeding...","required":true,"type":"text"},{"id":"s3","label":"Findings - Gestational Sac","placeholder":"Intrauterine gestational sac present. Mean sac diameter: [X] mm. Location: [fundal/mid/lower]","required":true,"type":"text"},{"id":"s4","label":"Findings - Fetus","placeholder":"Crown-rump length: [X] mm. Fetal heart rate: [X] bpm. Fetal number: [single/twins]","required":true,"type":"text"},{"id":"s5","label":"Findings - Adnexa","placeholder":"Right adnexa: [normal/mass]. Left adnexa: [normal/mass]. Corpus luteum: [present/absent]","required":false,"type":"text"},{"id":"s6","label":"Estimated GA","placeholder":"By CRL: [X] weeks [X] days. By LMP: [X] weeks [X] days. EDD: [date]","required":true,"type":"text"},{"id":"s7","label":"Impression","placeholder":"1. Intrauterine pregnancy. 2. Viability: [viable/non-viable]. 3. Estimated GA: [X] weeks [X] days.","required":true,"type":"text"}]'::jsonb, '[]'::jsonb, false, 0),

('00000000-0000-0000-0000-000000000000', 'PET-CT - Oncology Staging', 'Format for PET-CT oncology staging and restaging', 'PET-CT',
'[{"id":"s1","label":"Technique","placeholder":"FDG PET-CT was performed from skull base to mid-thigh...","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Known malignancy, staging/restaging...","required":true,"type":"text"},{"id":"s3","label":"Findings - Primary","placeholder":"Primary site, size, SUVmax...","required":true,"type":"text"},{"id":"s4","label":"Findings - Nodal","placeholder":"Regional and distant lymph nodes with FDG uptake...","required":true,"type":"text"},{"id":"s5","label":"Findings - Metastatic","placeholder":"Distant metastatic sites...","required":true,"type":"text"},{"id":"s6","label":"Findings - Incidental","placeholder":"Incidental FDG uptake, non-malignant findings...","required":false,"type":"text"},{"id":"s7","label":"Impression","placeholder":"1. Staging assessment... 2. Comparison with prior if applicable...","required":true,"type":"text"}]'::jsonb, '[]'::jsonb, false, 0),

('00000000-0000-0000-0000-000000000000', 'Mammography - Normal', 'Standard normal mammography report with BI-RADS', 'Mammography',
'[{"id":"s1","label":"Technique","placeholder":"Bilateral digital screening mammography...","required":true,"type":"text"},{"id":"s2","label":"Clinical Indication","placeholder":"Screening mammography...","required":true,"type":"text"},{"id":"s3","label":"Findings - Right","placeholder":"Breast composition, masses, calcifications, architectural distortion...","required":true,"type":"text"},{"id":"s4","label":"Findings - Left","placeholder":"Breast composition, masses, calcifications, architectural distortion...","required":true,"type":"text"},{"id":"s5","label":"BI-RADS","placeholder":"BI-RADS Category 1 - Negative","required":true,"type":"text"},{"id":"s6","label":"Impression","placeholder":"1. BI-RADS 1: Negative. Routine screening recommended in 1 year.","required":true,"type":"text"}]'::jsonb, '[]'::jsonb, true, 0);

-- ============ SYSTEM MACROS ============

INSERT INTO macros (user_id, trigger, expansion, category, description, usage_count) VALUES
('00000000-0000-0000-0000-000000000000', '/us-normal-abd', 'The liver is normal in size and echotexture without focal lesion. No intrahepatic biliary dilatation. The gallbladder is normal with no gallstones or wall thickening. The pancreas is normal in echotexture. The spleen is normal in size. Both kidneys show normal cortical thickness and echogenicity without hydronephrosis or calculus. The abdominal aorta is normal in caliber. No free fluid.', 'abdomen', 'Normal abdominal ultrasound', 0),
('00000000-0000-0000-0000-000000000000', '/us-normal-kidney', 'Both kidneys are normal in size with maintained cortical thickness and echogenicity. No hydronephrosis, calculus, or mass lesion identified. Corticomedullary differentiation is maintained.', 'abdomen', 'Normal kidneys ultrasound', 0),
('00000000-0000-0000-0000-000000000000', '/us-gallstones', 'Multiple echogenic foci within the gallbladder lumen demonstrating posterior acoustic shadowing, consistent with gallstones. Gallbladder wall thickness is within normal limits. No pericholecystic fluid. No sonographic Murphy sign.', 'abdomen', 'Gallstones finding', 0),
('00000000-0000-0000-0000-000000000000', '/us-kidney-stone', 'An echogenic focus with posterior acoustic shadowing is identified within the [right/left] kidney, measuring [X] mm, consistent with a calculus. [No/Minimal/Mild/Moderate/Severe] hydronephrosis is noted on the [right/left].', 'abdomen', 'Kidney stone finding', 0),
('00000000-0000-0000-0000-000000000000', '/us-normal-thyroid', 'The thyroid gland is normal in size and echotexture. No focal nodule or cyst identified. The isthmus is normal in thickness. No significant cervical lymphadenopathy.', 'general', 'Normal thyroid ultrasound', 0),
('00000000-0000-0000-0000-000000000000', '/us-normal-pelvis', 'The uterus is normal in size and echotexture. The endometrial thickness is within normal limits. Both ovaries are normal in size with normal follicular pattern. No adnexal mass or free fluid in the cul-de-sac.', 'general', 'Normal pelvic ultrasound', 0),
('00000000-0000-0000-0000-000000000000', '/ct-normal-chest', 'The lungs are clear bilaterally without focal consolidation, pleural effusion, or pneumothorax. The cardiac silhouette is within normal limits. The mediastinal and hilar contours are unremarkable. No pathologic lymphadenopathy. The thyroid gland is normal. The upper abdominal structures are unremarkable. The osseous structures are intact without acute fracture or suspicious lesion.', 'chest', 'Normal CT chest', 0),
('00000000-0000-0000-0000-000000000000', '/ct-normal-abd', 'The liver is normal in size and attenuation without focal lesion. No intrahepatic or extrahepatic biliary dilatation. The gallbladder is normal. The pancreas is normal without focal lesion or ductal dilatation. The spleen is normal in size. Both kidneys enhance symmetrically without focal lesion or hydronephrosis. No retroperitoneal or mesenteric lymphadenopathy. No free fluid or free air. The bowel is normal in caliber and enhancement. The osseous structures are intact.', 'abdomen', 'Normal CT abdomen/pelvis', 0),
('00000000-0000-0000-0000-000000000000', '/ct-normal-brain', 'No intracranial hemorrhage, mass effect, or midline shift. The gray-white matter differentiation is preserved. The ventricles and sulci are normal in size and configuration. No acute territorial infarction. The basal cisterns are patent. The calvarium and skull base are intact. No osseous abnormality.', 'neuro', 'Normal CT head', 0),
('00000000-0000-0000-0000-000000000000', '/mri-normal-brain', 'No abnormal signal intensity on any sequence. No evidence of acute infarction on DWI. No enhancing lesion following gadolinium administration. The ventricles are normal in size. No mass effect or midline shift. The major intracranial flow voids are preserved. The paranasal sinuses and mastoid air cells are clear. No abnormal meningeal enhancement.', 'neuro', 'Normal MRI brain', 0);
